func TestExtractModifiedFiles(t *testing.T) {
	t.Parallel()
	path := writeTestSession(t)
	files, pos, err := (&PiAgent{}).ExtractModifiedFilesFromOffset(path, 0)
	if err != nil {
		t.Fatal(err)
	}
	if len(files) != 1 || files[0] != "hello.txt" {
