20	// CalculateTokenUsage sums per-assistant-message token usage from a Pi JSONL
21	// transcript starting at the given line offset. Only assistant messages on
22	// the active conversation branch contribute to the totals — see
23	// pijsonl.ResolveActiveBranch for the rationale.
24	func (a *PiAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
25		usage := &agent.TokenUsage{}
26		err := pijsonl.ForEachActiveMessage(transcriptData, fromOffset, func(entry pijsonl.Entry) {
27			if entry.Message.Role != pijsonl.RoleAssistant || entry.Message.Usage == nil {
28				return
29			}
30			usage.InputTokens += entry.Message.Usage.Input
31			usage.OutputTokens += entry.Message.Usage.Output
32			usage.CacheReadTokens += entry.Message.Usage.CacheRead
33			usage.CacheCreationTokens += entry.Message.Usage.CacheWrite
34			usage.APICallCount++
35		})
36		return usage, err
37	}
38	
39	// ExtractModel returns the model identifier from the most recent assistant
40	// message on the active conversation branch. Pi records the model on every
41	// assistant message (message.model, e.g. "gpt-5.5") but never reports it through
42	// hooks, so the transcript is the only source. Using the most recent message
43	// reflects mid-session model changes. Returns "" when no active-branch assistant
44	// message carries a model.
45	func (a *PiAgent) ExtractModel(transcriptData []byte) (string, error) {
46		model := ""
47		err := pijsonl.ForEachActiveMessage(transcriptData, 0, func(entry pijsonl.Entry) {
48			if entry.Message.Role == pijsonl.RoleAssistant && entry.Message.Model != "" {
49				model = entry.Message.Model
50			}
51		})
52		return model, err
53	}
54	
55	// GetTranscriptPosition returns the JSONL line count of the file at path.
56	// Used by the strategy as the offset for incremental ExtractModifiedFiles
57	// calls. Missing files report 0 (consistent with Claude Code).
58	func (a *PiAgent) GetTranscriptPosition(path string) (int, error) {
59		if path == "" {
60			return 0, nil
61		}
62		//nolint:gosec // path from validated SessionRef set by lifecycle hooks
63		data, err := os.ReadFile(path)
64		if err != nil {
65			if os.IsNotExist(err) {
66				return 0, nil
67			}
68			return 0, fmt.Errorf("read pi transcript: %w", err)
69		}
70		return pijsonl.CountLines(data), nil
71	}
72	
73	// ExtractModifiedFilesFromOffset scans Pi assistant tool calls from startOffset
74	// onward and returns file paths touched by file-modifying tools (`write`,
75	// `edit`). Branch-aware: only counts entries on the active conversation
76	// branch.
77	func (a *PiAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) ([]string, int, error) {
78		if path == "" {
79			return nil, 0, nil
80		}
81		//nolint:gosec // path from validated SessionRef
82		data, err := os.ReadFile(path)
83		if err != nil {
84			return nil, 0, fmt.Errorf("read pi transcript: %w", err)
85		}
86	
87		totalLines := pijsonl.CountLines(data)
88		seen := make(map[string]bool)
89		var files []string
90	
91		err = pijsonl.ForEachActiveMessage(data, startOffset, func(entry pijsonl.Entry) {
92			if entry.Message.Role != pijsonl.RoleAssistant {
93				return
94			}
95			var items []pijsonl.ContentItem
96			if err := json.Unmarshal(entry.Message.Content, &items); err != nil {
97				return
98			}
99			for _, item := range items {
100				if item.Type != "toolCall" {
